CREATE TABLE `attendance_import_rows` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `import_id` bigint(20) unsigned NOT NULL,
  `row_no` int(10) unsigned NOT NULL,
  `biometric_id` varchar(50) NOT NULL,
  `punched_at` datetime NOT NULL,
  `punch_status` varchar(30) NOT NULL,
  `employee_id` bigint(20) unsigned DEFAULT NULL,
  `row_state` varchar(30) NOT NULL DEFAULT 'READY',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_air_row` (`import_id`,`row_no`),
  KEY `idx_air_unmatched` (`biometric_id`,`row_state`),
  KEY `fk_air_employee` (`employee_id`),
  CONSTRAINT `fk_air_employee` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`),
  CONSTRAINT `fk_air_import` FOREIGN KEY (`import_id`) REFERENCES `attendance_imports` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=11347 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
