CREATE TABLE `attendance_imports` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `cutoff_id` bigint(20) unsigned NOT NULL,
  `branch_id` bigint(20) unsigned DEFAULT NULL,
  `source_covered_through` date DEFAULT NULL,
  `original_name` varchar(255) NOT NULL,
  `stored_name` varchar(100) DEFAULT NULL,
  `file_hash` char(64) NOT NULL,
  `state` varchar(20) NOT NULL DEFAULT 'PREVIEW',
  `row_count` int(10) unsigned NOT NULL DEFAULT 0,
  `created_by` bigint(20) unsigned NOT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `imported_at` datetime DEFAULT NULL,
  `expires_at` datetime NOT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_ai_content` (`cutoff_id`,`branch_id`,`file_hash`),
  KEY `idx_ai_expiry` (`expires_at`,`deleted_at`),
  KEY `fk_ai_actor` (`created_by`),
  KEY `fk_ai_branch_auto_f067c4a9bf4a11f1aa4abcfce7d359e7` (`branch_id`),
  CONSTRAINT `fk_ai_actor` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_ai_branch_auto_f067c4a9bf4a11f1aa4abcfce7d359e7` FOREIGN KEY (`branch_id`) REFERENCES `branches` (`id`),
  CONSTRAINT `fk_ai_cutoff` FOREIGN KEY (`cutoff_id`) REFERENCES `payroll_cutoffs` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
