CREATE TABLE `employee_roster_rows` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `import_id` bigint(20) unsigned NOT NULL,
  `source_sheet` varchar(20) NOT NULL,
  `source_row` int(10) unsigned NOT NULL,
  `employee_code` varchar(50) DEFAULT NULL,
  `data_json` longtext NOT NULL,
  `action` varchar(20) NOT NULL DEFAULT 'AUTO',
  `employee_id` bigint(20) unsigned DEFAULT NULL,
  `imported_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_eri_source` (`import_id`,`source_sheet`,`source_row`),
  KEY `idx_eri_code` (`employee_code`),
  KEY `idx_eri_employee` (`employee_id`),
  CONSTRAINT `fk_eri_rows_employee` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_eri_rows_import` FOREIGN KEY (`import_id`) REFERENCES `employee_roster_imports` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=359 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
