--
-- Table structure for table `employees`
--

DROP TABLE IF EXISTS `employees`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `employees` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `employee_no` varchar(50) DEFAULT NULL,
  `user_id` bigint(20) unsigned DEFAULT NULL,
  `first_name` varchar(100) NOT NULL,
  `middle_name` varchar(100) DEFAULT NULL,
  `last_name` varchar(100) NOT NULL,
  `suffix` varchar(30) DEFAULT NULL,
  `preferred_name` varchar(100) DEFAULT NULL,
  `company_email` varchar(190) DEFAULT NULL,
  `personal_email` varchar(190) DEFAULT NULL,
  `mobile_no` varchar(50) DEFAULT NULL,
  `birth_date` date DEFAULT NULL,
  `place_of_birth` varchar(150) DEFAULT NULL,
  `gender` varchar(30) DEFAULT NULL,
  `civil_status` varchar(30) DEFAULT NULL,
  `nationality` varchar(100) DEFAULT NULL,
  `address_text` varchar(255) DEFAULT NULL,
  `permanent_address_text` varchar(255) DEFAULT NULL,
  `department_id` bigint(20) unsigned DEFAULT NULL,
  `position_id` bigint(20) unsigned DEFAULT NULL,
  `branch_id` bigint(20) unsigned DEFAULT NULL,
  `employment_type_id` bigint(20) unsigned DEFAULT NULL,
  `manager_employee_id` bigint(20) unsigned DEFAULT NULL,
  `hire_date` date DEFAULT NULL,
  `regularization_date` date DEFAULT NULL,
  `probation_start_date` date DEFAULT NULL,
  `probation_end_date` date DEFAULT NULL,
  `status` varchar(30) NOT NULL DEFAULT 'ACTIVE',
  `profile_photo_original_name` varchar(255) DEFAULT NULL,
  `profile_photo_stored_name` varchar(255) DEFAULT NULL,
  `profile_photo_mime_type` varchar(120) DEFAULT NULL,
  `profile_photo_updated_at` datetime DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `updated_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `business_unit_id` bigint(20) unsigned DEFAULT NULL,
  `legal_entity_id` bigint(20) unsigned DEFAULT NULL,
  `roster_full_name` varchar(190) DEFAULT NULL,
  `roster_group` varchar(20) DEFAULT NULL,
  `roster_needs_details` tinyint(1) NOT NULL DEFAULT 0,
  `roster_pending_json` longtext DEFAULT NULL,
  `roster_original_code` varchar(50) DEFAULT NULL,
  `roster_source_key` char(64) DEFAULT NULL,
  `directory_company_group` varchar(8) DEFAULT NULL,
  `directory_role` varchar(30) DEFAULT NULL,
  `directory_area_ids` varchar(1000) DEFAULT NULL,
  `lee_code` varchar(30) DEFAULT NULL,
  `payroll_group` varchar(30) DEFAULT NULL,
  `directory_section_id` bigint(20) unsigned DEFAULT NULL,
  `work_company` varchar(10) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `employee_no` (`employee_no`),
  UNIQUE KEY `user_id` (`user_id`),
  UNIQUE KEY `company_email` (`company_email`),
  UNIQUE KEY `uq_erf_source_key` (`roster_source_key`),
  UNIQUE KEY `uq_employees_lee_code` (`lee_code`),
  KEY `idx_employees_name` (`last_name`,`first_name`),
  KEY `idx_employees_status` (`status`),
  KEY `idx_employees_org` (`department_id`,`position_id`,`branch_id`),
  KEY `idx_employees_hire_date` (`hire_date`),
  KEY `fk_employees_position` (`position_id`),
  KEY `fk_employees_branch` (`branch_id`),
  KEY `fk_employees_employment_type` (`employment_type_id`),
  KEY `fk_employees_created_by` (`created_by`),
  KEY `fk_employees_updated_by` (`updated_by`),
  KEY `idx_employees_manager` (`manager_employee_id`),
  KEY `fk_eri_employees_business_unit` (`business_unit_id`),
  KEY `fk_eri_employees_legal_entity` (`legal_entity_id`),
  KEY `idx_erf_needs_details` (`roster_needs_details`),
  KEY `idx_employees_probation_end` (`probation_end_date`),
  KEY `idx_employees_payroll_group` (`payroll_group`),
  KEY `idx_employees_directory_section` (`directory_section_id`),
  CONSTRAINT `fk_employees_branch` FOREIGN KEY (`branch_id`) REFERENCES `branches` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_employees_created_by` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_employees_department` FOREIGN KEY (`department_id`) REFERENCES `departments` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_employees_directory_section` FOREIGN KEY (`directory_section_id`) REFERENCES `directory_sections` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_employees_employment_type` FOREIGN KEY (`employment_type_id`) REFERENCES `employment_types` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_employees_manager` FOREIGN KEY (`manager_employee_id`) REFERENCES `employees` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_employees_position` FOREIGN KEY (`position_id`) REFERENCES `positions` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_employees_updated_by` FOREIGN KEY (`updated_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_employees_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_eri_employees_business_unit` FOREIGN KEY (`business_unit_id`) REFERENCES `business_units` (`id`) ON DELETE SET NULL,
  CONSTRAINT `fk_eri_employees_legal_entity` FOREIGN KEY (`legal_entity_id`) REFERENCES `legal_entities` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=380 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

